/**
 * @method
 * @name scwin.tx_fn_ApplyJoin
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_ApplyJoin = async function () {
    const sbmOptions = {
        id: "tx_fn_ApplyJoin",
        method: "post",
        action: "/register/corpDiscls.do",
        ref: "dma_ApplyJoinReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil40204.tx_fn_ApplyJoin" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


